        maxGold=std::max(maxGold,float(session->config().players[player].states.at(1)));if(kills<100 && session->simulationTime()>=nextOrder){troops.clear();for(auto& [id,u]:session->units())if(u->owner==player && u->type!=ObjectData::code("hpea") && !u->building && !u->hidden() && f(u->life)>0 && session->canControlUnit(player,*u) && session->hasWeapon(id))troops.push_back(id);if(troops.empty()){nextOrder=session->simulationTime()+8;session->advance(.25);continue;}std::uint32_t target=0;float score=1e30f;std::shared_ptr<UnitState> base;for(auto& [id,u]:session->units())if(u->owner==player && u->type==ObjectData::code("htow") && f(u->life)>0){base=u;break;}for(auto& [id,u]:session->units()){bool threat=base && u->owner==6 && !u->building && std::hypot(f(u->x)-f(base->x),f(u->y)-f(base->y))<1100;bool valid=threat || (u->owner==8 && citizen(u->type)) || ((u->owner==2 || u->owner==8) && u->type==ObjectData::code("nzom")) || ((u->owner==10 || u->owner==11) && house(u->type));if(!valid || u->hidden() || f(u->life)<=0 || !session->unitVisibleTo(id,player))continue;float nearest=1e30f;for(auto id2:troops)if(session->units().contains(id2) && f(session->units().at(id2)->life)>0){auto troop=session->units().at(id2);nearest=std::min(nearest,std::hypot(f(troop->x)-f(u->x),f(troop->y)-f(u->y)));}float priority=(threat?-20000.f:house(u->type)?10000.f:0.f)+nearest;if(priority<score){score=priority;target=id;}}if(target){PlayerCommand attack;attack.player=player;attack.kind=PlayerCommandKind::TargetOrder;attack.order=851983;attack.target=target;attack.units=troops;if(dispatchPlayerCommand(*session,attack)){if(house(session->units().at(target)->type))orderedHouses.insert(target);for(auto id:troops)if(!initialFootmen.contains(id) && session->units().contains(id)){auto unit=session->units().at(id);if(unit->type==ObjectData::code("hfoo") && unit->combat.target==target)deployedRecruits.insert(id);}}}else{auto leader=session->units().at(troops.front());constexpr float dx[]={-1,0,1,0},dy[]={0,-1,0,1};auto direction=scout++%4;PlayerCommand explore;explore.player=player;explore.kind=PlayerCommandKind::GroundAttack;explore.units=troops;explore.xBits=std::bit_cast<std::uint32_t>(f(leader->x)+dx[direction]*900);explore.yBits=std::bit_cast<std::uint32_t>(f(leader->y)+dy[direction]*900);dispatchPlayerCommand(*session,explore);}nextOrder=session->simulationTime()+(target?8:25);}
