void human08ReachableShip(const wchar_t* root){auto session=start(root,"Maps\\Campaign\\Human08.w3m");while(session->simulationTime()<100)session->advance(.25);auto player=session->localPlayer().value_or(1);auto target=session->runtime().global("gg_unit_nbsp_0110").bits;require(session->userControl() && session->units().contains(target) && session->unitVisibleTo(target,player),"Human08 target unavailable");std::vector<std::uint32_t> mortars;for(auto& [id,u]:session->units())if(u->owner==player && u->type==ObjectData::code("hmtm") && std::bit_cast<float>(u->life.bits())>0)mortars.push_back(id);require(!mortars.empty(),"Human08 mortar missing");PlayerCommand cmd;cmd.player=player;cmd.kind=PlayerCommandKind::TargetOrder;cmd.units=mortars;cmd.order=851983;cmd.target=target;require(dispatchPlayerCommand(*session,cmd)>0,"Human08 reachable ship attack rejected");auto accepted=std::find_if(mortars.begin(),mortars.end(),[&](auto id){return session->units().at(id)->combat.target==target;});require(accepted!=mortars.end(),"Human08 accepted attack target missing");auto unit=session->units().at(*accepted);auto ship=session->units().at(target);require(!unit->route.empty(),"Human08 attack route missing");auto end=unit->route.back();require(std::hypot(std::bit_cast<float>(end.x.bits())-std::bit_cast<float>(ship->x.bits()),std::bit_cast<float>(end.y.bits())-std::bit_cast<float>(ship->y.bits()))<=1222.01f,"Human08 attack route outside range");}
